def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_aggressive = 0
    weak_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                weak_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 80 and opp.get('budget', 0) >= 120:
                    rich_aggressive += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water_days >= 2:
        urgency += 1.0
    elif no_water_days >= 1:
        urgency += 0.45

    base = 18.0 + 22.0 * scarcity + 10.0 * urgency

    if supply >= 23:
        base -= 8.0
    elif supply <= 17:
        base += 10.0

    if highest_prev >= 140:
        if urgency < 0.9:
            bid = base * 0.75
        else:
            bid = max(base + 10.0, 0.78 * highest_prev)
    elif highest_prev >= 90:
        if rich_aggressive >= 2 and urgency < 0.8:
            bid = max(base, avg_prev * 0.72)
        else:
            bid = max(base, min(highest_prev + 2.0, avg_prev + 12.0))
    elif highest_prev > 0:
        bid = max(base, highest_prev + 1.5)
    else:
        bid = base

    if weak_opp >= 2 and urgency < 0.7:
        bid -= 4.0

    if day >= 8:
        bid += 6.0 * urgency + 3.0 * scarcity

    if budget < 60:
        bid = min(bid, max(12.0, budget * 0.72))
    elif budget < 120:
        bid = min(bid, budget * 0.82)
    else:
        bid = min(bid, budget * 0.9)

    floor_bid = 8.0
    if urgency >= 1.0:
        floor_bid = 28.0
    elif urgency >= 0.45:
        floor_bid = 20.0

    bid = max(floor_bid, bid)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 0.65

    if my_hp <= 1:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp == 2:
        base_bid = DAILY_SALARY * 0.85
    elif my_hp == 3:
        base_bid = DAILY_SALARY * 0.75

    supply_pressure_factor = 1.0
    if current_supply < WATER_REQ * (len(alive_opponents) + 1) * 1.5:
        if current_supply <= MIN_SUPPLY + 2:
            supply_pressure_factor = 1.15
        elif current_supply <= MIN_SUPPLY + 5:
            supply_pressure_factor = 1.05
        elif current_supply >= MAX_SUPPLY - 2:
            supply_pressure_factor = 0.9

    base_bid *= supply_pressure_factor

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if my_hp <= 3:
            if highest_prev_bid >= base_bid * 0.9:
                final_bid = max(base_bid, highest_prev_bid + 5)
            else:
                final_bid = base_bid
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.8:
                final_bid = max(base_bid, highest_prev_bid * 0.9)
            elif highest_prev_bid >= base_bid * 0.9:
                final_bid = max(base_bid, highest_prev_bid + 1)
            else:
                final_bid = base_bid
    else:
        final_bid = base_bid

    final_bid = min(final_bid, my_budget)
    final_bid = max(0.0, final_bid)

    if EPISODE_DAYS - current_day == 0:
        final_bid = my_budget

    return final_bid

